text:
& .state,
& .sort-header-details {
  display: none;
}

& .read-status-column {
  inline-size: var(--read-status-size);
}

& .read-status {
  display: var(--read-status-display, none);
  content: var(--read-status-icon);
  block-size: var(--read-status-size);
  inline-size: var(--read-status-size);
  -moz-context-properties: fill, stroke;
  fill: var(--read-status-fill);
  stroke: var(--read-status-stroke);
}
